set
  title = 'Anatomy and Physiology II (with Lab)',
  goal = 'Anatomy and Physiology II (with Lab)',
  summary = 'Designed as a 15-module undergraduate kinesiology course with integrated lecture and lab. Each module can map to one week in a semester format, or to a compressed systems block with lab practicals, physiology experiments, data reporting, and applied movement-science case work.',
  data = $ap2labjson${"slug": "anatomy-and-physiology-ii-with-lab", "title": "Anatomy and Physiology II (with Lab)", "description": "Designed as a 15-module undergraduate kinesiology course with integrated lecture and lab. Each module can map to one week in a semester format, or to a compressed systems block with lab practicals, physiology experiments, data reporting, and applied movement-science case work.", "topics": [{"id": "7e82ba14-5508-414e-a966-0e0df478ae6b", "type": "topic", "title": "A&P II Orientation, Homeostasis Review, Lab Safety, and Measurement", "description": "Re-anchor students in systems physiology, safe lab practice, and quantitative observation.", "children": [{"id": "e8bf5d14-c9cb-457b-b12e-968a8198e0bd", "type": "subtopic", "title": "Homeostasis and systems integration", "description": "Students revisit the central logic of physiology before moving into organ-system interactions.", "children": [{"id": "14a5ef2e-2a14-425a-b50f-0c0a8fca6625", "type": "concept", "title": "Negative and positive feedback"}, {"id": "f1022d98-1a24-4ccc-a503-9fe0d113a090", "type": "concept", "title": "Set points, effectors, receptors, and control centers"}, {"id": "4f888fdf-c52a-4863-b2fb-c8e7d6e11113", "type": "concept", "title": "Integration across cardiovascular, respiratory, renal, endocrine, digestive, and immune systems"}]}, {"id": "f2a3d271-52a6-46e8-b4f9-f8b943c8ba32", "type": "subtopic", "title": "Lab safety and scientific measurement", "description": "The goal is to collect data safely, accurately, and ethically.", "children": [{"id": "6f911ac5-5acf-424e-bf08-14c8dbc9c7b1", "type": "concept", "title": "PPE, biological materials, equipment handling, and emergency procedures"}, {"id": "e7dbea0e-d9b5-4a0f-83b7-23bcff7e664e", "type": "concept", "title": "Units, calibration, measurement error, and reliability"}, {"id": "594a5741-f079-4297-862e-78ec9deba930", "type": "concept", "title": "Human-subject respect, consent, and privacy in lab activities"}]}, {"id": "05